 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    marks = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    rows = {r for r in range(h) if sum(rr == r for rr, _ in marks) >= 2}
    cols = {c for c in range(w) if sum(cc == c for _, cc in marks) >= 2}
    # Paired markers draw full horizontal and vertical lines.
    for r in rows:
        out[r] = [1] * w
    for c in cols:
        for r in range(h):
            out[r][c] = 1
    # Any 4-connected 2-object touched by a drawn line is converted in full.
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                x, y = stack.pop()
                component.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 2 and (nx,ny) not in seen:
                        seen.add((nx,ny)); stack.append((nx,ny))
            if any(x in rows or y in cols for x, y in component):
                for x, y in component:
                    out[x][y] = 1
    return out

